/*
 * Compatibility stand-in, not GSAP's ScrollTrigger: defines the name that
 * pages generated by earlier versions pass to gsap.registerPlugin() and call
 * in scripts stored in the page. create() and batch() run their onEnter
 * callback once; every other call does nothing. See gsap.min.js.
 */
(function () {
  'use strict';

  var inert = new Proxy(function () {}, {
    get: function (target, property) {
      if (property === 'then') {
        return undefined;
      }
      if (property === Symbol.toPrimitive) {
        return function () { return 0; };
      }
      if (property === Symbol.iterator) {
        return function () { return [][Symbol.iterator](); };
      }
      return inert;
    },
    apply: function () {
      return inert;
    }
  });

  function onEnter(vars, argument) {
    if (vars && typeof vars.onEnter === 'function') {
      try {
        vars.onEnter(argument);
      } catch (e) {
        // A failing callback must not stop the rest of the stored script.
      }
    }
  }

  function elements(target) {
    if (typeof target === 'string') {
      try {
        return Array.prototype.slice.call(document.querySelectorAll(target));
      } catch (e) {
        return [];
      }
    }
    return target && target.nodeType === 1 ? [target] : [];
  }

  var scrollTrigger = {
    create: function (vars) { onEnter(vars, inert); return inert; },
    batch: function (target, vars) { onEnter(vars, elements(target)); return []; }
  };

  window.ScrollTrigger = window.ScrollTrigger || new Proxy(scrollTrigger, {
    get: function (target, property) {
      return property in target ? target[property] : inert;
    }
  });
})();
